import {courses,searchCourses} from './courses.js';
import {courseRoute} from './navigation.js';
import {escape,icon} from './quiz-view.js';
import {byteMascot} from './mascot.js';

export function courseCardsMarkup(query,progressByCourse={}) {
  const matches=searchCourses(query);
  if(!matches.length) return `<div class="catalog-empty">${icon('search')}<h3>Belum ketemu pelajaran yang cocok.</h3><p>Coba kata lain, misalnya Python, C, atau pemrograman.</p></div>`;
  return matches.map(c=> {
    const progress=progressByCourse[c.id]??{solvedCount:0};
    return `<article class="catalog-course-card" data-tone="${c.tone}"><div class="catalog-card-top"><span class="catalog-course-symbol" aria-hidden="true">${escape(c.symbol)}</span><span class="catalog-level">${escape(c.level)}</span></div><p class="catalog-category">${escape(c.category)}</p><h3><a href="${courseRoute(c.id)}" data-course="${c.id}">${escape(c.title)}</a></h3><p class="catalog-description">${escape(c.description)}</p><div class="catalog-course-meta"><span>${icon('book')} ${c.topicCount} topik</span><span>${icon('bolt')} ${c.exerciseCount} latihan</span></div><div class="catalog-course-progress"><span>${progress.solvedCount}/${c.exerciseCount} latihan dikuasai</span><strong>${Math.round(progress.solvedCount/c.exerciseCount*100)}%</strong></div><progress max="${c.exerciseCount}" value="${progress.solvedCount}" aria-label="Progres ${escape(c.title)}"></progress><a class="primary catalog-course-link" href="${courseRoute(c.id)}" data-course="${c.id}">${progress.solvedCount?'Lanjutkan pelajaran':'Lihat pelajaran'} ${icon('arrow')}</a></article>`;
  }).join('')+(!query.trim()?`<aside class="catalog-future-card"><span class="future-symbol" aria-hidden="true">${icon('layers')}</span><span class="catalog-category">Katalog terus berkembang</span><h3>Masih banyak hal seru untuk dipelajari.</h3><p>Pelajaran baru akan muncul di sini saat materinya siap. Semua petualanganmu punya tempat sendiri.</p><span class="future-note">Ruang untuk rasa ingin tahu berikutnya.</span></aside>`:'');
}
export function catalogMarkup({stats,rewards,progressByCourse,continueTopic,query='',showGuide=false}) {
  const available=courses.filter(c=>c.status==='available').length;
  return `<div class="page-top"><span class="catalog-page-label">${icon('home')} Beranda</span>${rewards}</div><header class="page-heading catalog-heading"><h1 tabindex="-1">Mau belajar apa hari ini?</h1><p>Pilih pelajaranmu. Mulai kecil, lalu jadi makin jago.</p></header>
    <div class="catalog-top"><section class="catalog-hero"><div class="catalog-hero-copy"><span class="section-kicker">Satu tempat, banyak petualangan</span><h2>Hal baru.<br>Makin seru.</h2><p>Ikuti rasa ingin tahumu lewat latihan, teka-teki, dan tantangan kecil yang bikin paham.</p><button class="primary" data-action="browse-courses">Pilih pelajaran ${icon('arrow')}</button></div><div class="catalog-hero-character">${byteMascot('idle')}<span>Belajar bareng Byte!</span></div></section>
    <aside class="journey-panel daily-panel catalog-goal"><div class="panel-title">${icon('target')}<h2>Misi harian</h2></div><div class="daily-count"><span class="big-number">${Math.min(stats.todayCount,5)}<span>/5</span></span><span>soal benar<br>hari ini</span><span class="goal-trophy" aria-hidden="true">${icon('trophy')}</span></div><progress max="5" value="${Math.min(stats.todayCount,5)}" aria-label="Target harian lima soal benar"></progress><p class="goal-status">${stats.todayCount>=5?'Misi selesai. Hebat!':`Tinggal ${5-stats.todayCount} soal lagi. Bisa, yuk!`}</p><p class="journey-note">Lima soal dari pelajaran mana saja menjaga streak-mu. Langkah kecil tetap berarti.</p></aside></div>
    ${continueTopic?`<section class="catalog-resume" aria-label="Lanjutkan pelajaran terakhir"><span class="resume-symbol" aria-hidden="true">${escape(continueTopic.symbol)}</span><div><span class="section-kicker">Lanjutkan langkahmu</span><h2>${escape(continueTopic.title)}</h2><p>${escape(continueTopic.courseTitle)} · jawaban dan progresmu sudah tersimpan.</p></div><button class="secondary" data-topic="${continueTopic.id}" data-course-id="${continueTopic.courseId}">Lanjut belajar ${icon('arrow')}</button></section>`:''}
    <section class="catalog-courses" id="catalog-courses" aria-labelledby="catalog-title"><div class="catalog-section-header"><div><span class="section-kicker">Temukan kesukaanmu</span><h2 id="catalog-title">Jelajahi pelajaran</h2><p id="course-result-count" role="status">${query.trim()?`${searchCourses(query).length} pelajaran ditemukan`:`${available} pelajaran tersedia`}</p></div><div class="course-search"><label class="sr-only" for="course-search">Cari pelajaran</label>${icon('search')}<input id="course-search" type="search" placeholder="Cari pelajaran…" value="${escape(query)}" autocomplete="off" maxlength="100" aria-controls="course-results"></div></div><div id="course-results" class="catalog-course-grid">${courseCardsMarkup(query,progressByCourse)}</div></section>
    <footer class="page-footer catalog-footer"><span>Rasa ingin tahu adalah awal yang bagus.</span><button class="text-button" data-action="guide" aria-expanded="${showGuide}">Cara belajar ${showGuide?'−':'+'}</button></footer>
    ${showGuide?`<section class="guide catalog-guide" aria-label="Cara belajar"><h2>Mulai dari hal yang membuatmu penasaran.</h2><ol><li>Pilih pelajaran di katalog untuk melihat topiknya.</li><li>Ikuti latihan dan baca penjelasan jawabannya.</li><li>Soal yang belum tepat akan diulang di akhir putaran. Kamu bisa mencoba lagi tanpa batas nyawa.</li></ol><p>Progres dan jawaban tersimpan otomatis di browser ini. Jawab lima soal berbeda dengan benar dari pelajaran mana saja untuk mencapai misi harian. XP didapat saat pertama kali menjawab soal dengan benar.</p></section>`:''}`;
}
